const filename = 'u.dat';

var 
  f: file;
  r: real;
  s: string[10];
  k: integer;
  c: char;

begin
  if not FileExists(filename) then
  begin
    assign(f,filename);
    rewrite(f);
    writeln('Writing to file ',filename);

    r := random*10; 
    for var i:=0 to 10 do
      s := s + Chr(Ord('A')+Random(26));
    c := Chr(Ord('A')+Random(26));
    k := Random(100);

    writeln(r);
    writeln(c);
    writeln(k);
    write(f,r);
    write(f,c);
    write(f,k);
    close(f);  
  end
  else 
  begin
    assign(f,filename);
    reset(f);
    writeln('Reading from file ',filename);
    read(f,r,c,k);
    writeln(r);
    writeln(c);
    writeln(k);
    close(f);  
    erase(f);
  end;  
end.

