    var Right := tb1.Text.ToReal;
    case b.Text of
      $'+': lb1.Content := '= ' + (Left + Right);
      $'-': lb1.Content := '= ' + (Left - Right);
      $'*': lb1.Content := '= ' + (Left * Right);
      $'/': lb1.Content := '= ' + (Left / Right);
